import * as grpc from "@grpc/grpc-js";
import {
	GATEWAY_REQUEST_SLOT_MS,
	GATEWAY_REQUEST_WINDOW_SLOTS,
	gatewayRequestSlotStart
} from "@kena/shared";
import { redisAdapter } from "../infrastructure/redis/index.js";
import { LogType, logger } from "./Logger.js";

/**
 * Contador en memoria de peticiones despachadas del gateway hacia los cores.
 *
 * Estado a nivel de módulo, no una clase: `packages/gateway/src/index.ts`
 * levanta un único `GrpcServer` y el proceso corre en `fork` con
 * `instances: 1`, así que un solo buffer ve la flota entera y no hay
 * agregación entre procesos que resolver.
 *
 * Lo que se cuenta: peticiones de dominio despachadas módulo→core. Incluye las
 * que el core resuelve de su caché Redis sin llamar a discord.com, y NO incluye
 * ni el tráfico REST que el core origina por su cuenta ni los eventos
 * core→módulo, que viajan por Pub/Sub sin tocar el gateway.
 *
 * Lo que se persiste: UNA sola clave en Redis con una ventana rodante de
 * `GATEWAY_REQUEST_WINDOW_SLOTS` minutos. El agregado vive en memoria y se
 * vuelca cada 10 s; Redis nunca ve una clave por volcado.
 */

const FLUSH_INTERVAL_MS = 10_000;

/**
 * Tope de combinaciones distintas retenidas entre volcados. Cinco dimensiones
 * multiplicadas se disparan si un módulo empieza a inventar nombres de método;
 * el cap acota la memoria del buffer sin perder el total, que se acumula en
 * `__overflow__`. Mismo espíritu que el cap de `library-bandwidth/src/store.ts`.
 */
const MAX_FIELDS = 20_000;

const OVERFLOW_DIMENSIONS = "__overflow__";

/**
 * Cada cuánto se barre el hash entero buscando minutos que ya no caben en la
 * ventana.
 *
 * El borrado normal usa `writtenBySlot`, que es exacto y no cuesta lecturas
 * —pero vive en memoria del proceso—. Al reiniciar, todo lo escrito antes se
 * queda huérfano: nadie lo va a borrar y el TTL de la clave se renueva en cada
 * volcado, así que tampoco caduca. El barrido cierra ese agujero sin depender
 * de que el proceso recuerde nada.
 *
 * Diez minutos: el primero corre al arrancar (que es cuando hay huérfanos que
 * limpiar) y el resto son un `HSCAN` cada 600 volcados.
 */
const SWEEP_INTERVAL_MS = 10 * 60_000;

/**
 * Kill switch sin secreto en Infisical: se lee `process.env` directo, igual que
 * `GATEWAY_HTTP_PORT` en `api/HttpApiServer.ts`.
 */
const DISABLED = process.env.GATEWAY_REQUEST_METRICS_DISABLED === "1";

/** Combinación de dimensiones → peticiones acumuladas desde el último volcado. */
let counters = new Map<string, number>();

/**
 * Campos ya escritos en Redis, por slot. Es lo que permite borrar un minuto
 * entero cuando sale de la ventana sin tener que escanear el hash: el gateway
 * es el único escritor, así que sabe exactamente qué campos puso.
 */
const writtenBySlot = new Map<number, Set<string>>();

let flushTimer: NodeJS.Timeout | null = null;
let overflowWarned = false;
/** 0 = nunca barrido: el primer volcado tras arrancar hace la limpieza. */
let lastSweepAt = 0;

/**
 * Traduce el rechazo de `dispatch` al nombre del `grpc.status`. Todos los
 * caminos de rechazo —locales (UNAVAILABLE, DEADLINE_EXCEEDED,
 * INVALID_ARGUMENT) y el que reenvía el `grpc_status` del core— adjuntan un
 * `code` numérico; cualquier otra cosa cae en `"UNKNOWN"`.
 */
export function grpcStatusLabel(err: unknown): string {
	if (err && typeof err === "object" && "code" in err) {
		const code: unknown = err.code;
		if (typeof code === "number" && grpc.status[code]) return grpc.status[code];
		if (typeof code === "string" && code) return code;
	}
	return "UNKNOWN";
}

export function recordGatewayRequest(
	botId: string,
	moduleId: string,
	service: string,
	method: string,
	status: string
): void {
	if (DISABLED) return;

	const dimensions = `${botId || "unknown"}|${moduleId || "gateway"}|${service}|${method}|${status}`;
	const current = counters.get(dimensions);
	if (current === undefined && counters.size >= MAX_FIELDS) {
		counters.set(OVERFLOW_DIMENSIONS, (counters.get(OVERFLOW_DIMENSIONS) ?? 0) + 1);
		if (!overflowWarned) {
			overflowWarned = true;
			logger.warn(LogType.GRPC, "[metrics] request counter cardinality cap reached", {
				cap: MAX_FIELDS,
				dropped_field: dimensions
			});
		}
	} else {
		counters.set(dimensions, (current ?? 0) + 1);
	}

	if (!flushTimer) {
		// `.unref()`: el contador nunca debe ser la razón de que el proceso siga
		// vivo. El apagado limpio hace su propio volcado final.
		flushTimer = setInterval(() => void flushGatewayRequestMetrics(), FLUSH_INTERVAL_MS);
		flushTimer.unref();
	}
}

/**
 * Vuelca el buffer a la clave de ventana y espera a que termine.
 *
 * Si el pipeline falla se descarta el volcado: reinyectarlo convertiría un
 * Redis caído durante minutos en una fuga de memoria dentro del proceso que
 * sostiene toda la malla gRPC.
 */
export async function flushGatewayRequestMetrics(): Promise<void> {
	const slot = gatewayRequestSlotStart(Date.now());
	const oldestSlot = slot - (GATEWAY_REQUEST_WINDOW_SLOTS - 1) * GATEWAY_REQUEST_SLOT_MS;

	// Campos de los minutos que acaban de salir de la ventana. Se calculan
	// aunque no haya tráfico nuevo: un gateway ocioso también tiene que dejar
	// de acumular pasado. Los slots NO se olvidan hasta que Redis confirma el
	// borrado, para que un volcado fallido no deje los campos huérfanos en el
	// hash hasta que expire la clave entera.
	const expiredSlots: number[] = [];
	const expiredFields: string[] = [];
	for (const [writtenSlot, fields] of writtenBySlot) {
		if (writtenSlot >= oldestSlot) continue;
		expiredSlots.push(writtenSlot);
		expiredFields.push(...fields);
	}

	if (counters.size === 0 && expiredFields.length === 0) return;

	const snapshot = counters;
	counters = new Map<string, number>();
	overflowWarned = false;

	const increments = new Map<string, number>();
	const slotFields = writtenBySlot.get(slot) ?? new Set<string>();
	for (const [dimensions, count] of snapshot) {
		const field = `${slot}|${dimensions}`;
		increments.set(field, count);
		slotFields.add(field);
