 * importa es no perder el volcado, no limpiar. Un fallo aquí se traga con un
 * warn — es mantenimiento, y reintentarlo cuesta diez minutos de espera, no un
 * dato perdido.
 */
async function sweepStaleFields(oldestSlot: number): Promise<void> {
	const now = Date.now();
	if (now - lastSweepAt < SWEEP_INTERVAL_MS) return;
	lastSweepAt = now;

	try {
		const removed = await redisAdapter.cache.gateway.requestMetrics.pruneOlderThan(oldestSlot);
		if (removed > 0) {
			logger.info(LogType.REDIS, "[metrics] swept request counter fields outside the window", {
				removed,
				oldest_slot: new Date(oldestSlot).toISOString()
			});
		}
	} catch (err) {
		logger.warn(LogType.REDIS, "[metrics] request counter sweep failed", {
			error: err instanceof Error ? err.message : String(err)
		});
	}
}

